describe('Assign Category to Record via Dropdown', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should successfully assign a category to a record via dropdown', () => {
    // Verify initial state: no category assigned
    cy.get('[data-testid="record-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="record-item"]').first().should('contain', 'No Category');

    // Intercept API call to assign category
    cy.intercept('POST', '/api/records/1/assign-category').as('assignCategory');

    // Select a category from the dropdown
    cy.get('[data-testid="category-dropdown"]').click();
    cy.get('[data-testid="category-option"]').click({ force: true });
    cy.get('[data-testid="category-option-finance"]').click();

    // Verify category is selected
    cy.get('[data-testid="category-dropdown"]').should('contain', 'Finance');

    // Verify API call was made
    cy.wait('@assignCategory').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify category is now assigned
    cy.get('[data-testid="record-item"]').first().should('contain', 'Finance');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Category assigned successfully');
  });

  it('should handle edge case: selecting disabled category option', () => {
    // Verify initial state: no category assigned
    cy.get('[data-testid="record-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').should('have.length.greaterThan', 0);

    // Intercept API call to assign category
    cy.intercept('POST', '/api/records/1/assign-category').as('assignCategory');

    // Select a disabled category from the dropdown
    cy.get('[data-testid="category-dropdown"]').click();
    cy.get('[data-testid="category-option"]').click({ force: true });
    cy.get('[data-testid="category-option-disabled"]').click();

    // Verify disabled option is not selected
    cy.get('[data-testid="category-dropdown"]').should('not.contain', 'Disabled');

    // Verify API call was not made
    cy.wait('@assignCategory').then((interception) => {
      expect(interception.request.body.category).to.equal('Disabled');
      expect(interception.response.statusCode).to.equal(400);
    });

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Category cannot be disabled');
  });
});
